<!-- Generated by agenticspec ui generate from the ess-ui/1 document of `desk`. Never edit: change
     the document and generate again. -->
<script setup lang="ts">
import { computed } from 'vue';
import { KitButton, KitEmpty, KitField, KitForm, KitLink, KitList, KitMetric, KitPanel, KitSearch, KitSelect, KitShell, KitStack, KitTable, KitTextInput, KitToolbar, type FieldDef } from '@kit';
import { contains, groupRows, metricValue, same, sortRows, text, useActions, useCommand, useConfirm, useForm, usePage, usePoll, useRead, useShell } from '../runtime';
import type { Value } from '../client';

const shell = useShell();
const may = useActions();
const page = usePage({ params: [], state: { owner: { store: 'url', initial: '' }, search: { store: 'url', initial: '' } } });
const r_tickets_open_count = useRead('desk.Tickets', () => ({}));
const r_tickets_load = useRead('desk.Load', () => ({}));
const help_link = 'https://example.org/desk';
const c_tickets_close_all = useCommand('desk.CloseAll', () => ({}));
const cf_tickets_close_all = useConfirm();
const r_open = useRead('desk.Tickets', () => ({}));
usePoll(r_open, 30000);
const rows_open = computed(() => sortRows(r_open.rows.filter((row) => (same(row['state'], 'open') && (same(row['owner'], page.state['owner']) || same(page.state['owner'], null)))), 'opened_at', 'desc', false));
const fields_open: FieldDef[] = [
  { field: 'title', label: 'Title', as: 'text' },
  { field: 'owner', label: 'Owner', as: 'text' },
  { field: 'opened_at', label: 'Opened', as: 'timestamp' },
];
const c_open_close = useCommand('desk.CloseTicket', () => ({ ticket_id: null }));
const cf_open_close = useConfirm();
const groups_open = computed(() => groupRows(rows_open.value, 'priority', ['high', 'normal', 'low'], false));
const r_closed = useRead('desk.Tickets', () => ({}));
const rows_closed = computed(() => sortRows(r_closed.rows.filter((row) => (!same(row['state'], 'open') && contains(row['title'], page.state['search']))), 'minutes', 'asc', true));
const fields_closed: FieldDef[] = [
  { field: 'title', label: 'Title', as: 'text' },
  { field: 'minutes', label: 'Minutes', as: 'number' },
];
const f_new = useForm('desk.OpenTicket', { title: '', priority: null }, () => ({}));
</script>

<template>
  <KitShell :title="shell.title" page-title="Tickets" :theme="shell.theme" :themes="shell.themes" :toasts="shell.toasts" @update:theme="shell.setTheme" @dismiss="shell.dismiss">
    <template #bar>
      <KitToolbar label="Metrics">
        <KitMetric label="Tickets" :value="metricValue(r_tickets_open_count, 'count', null, null)" />
        <KitMetric label="Minutes" :value="metricValue(r_tickets_load, 'avg', 'minutes', null)" />
      </KitToolbar>
      <KitToolbar label="Help">
        Tickets of the desk by their state
        <KitLink :href="help_link">Help</KitLink>
      </KitToolbar>
      <KitToolbar label="Actions">
        <template v-if="may.allows('desk.CloseAll')">
          <template v-if="cf_tickets_close_all.at === true">
            Close every open ticket?
            <KitButton tone="danger" size="sm" :busy="c_tickets_close_all.busy" @click="cf_tickets_close_all.close(); c_tickets_close_all.run()">Close all</KitButton>
            <KitButton tone="ghost" size="sm" @click="cf_tickets_close_all.close()">Cancel</KitButton>
          </template>
          <KitButton v-else tone="primary" :busy="c_tickets_close_all.busy" :disabled="c_tickets_close_all.blocked" @click="cf_tickets_close_all.ask(true)">Close all</KitButton>
        </template>
      </KitToolbar>
    </template>
    <KitStack>
      <KitPanel name="open" title="Open" collapsible :state="r_open.state" :error="r_open.error" @retry="r_open.reload()">
        <KitPanel v-for="g in groups_open" :key="g.name" :name="g.name" :title="g.name" bare>
          <KitTable :label="'Open: ' + g.name" :columns="fields_open" :rows="g.rows" row-key="id">
            <template #actions="{ row }">
              <template v-if="may.allows('desk.CloseTicket')">
                <template v-if="cf_open_close.at === row">
                  Close this ticket?
                  <KitButton tone="danger" size="sm" :busy="c_open_close.busy" @click="cf_open_close.close(); c_open_close.run({ ticket_id: row['id'] as Value })">Close</KitButton>
                  <KitButton tone="ghost" size="sm" @click="cf_open_close.close()">Cancel</KitButton>
                </template>
                <KitButton v-else tone="ghost" size="sm" :busy="c_open_close.busy" @click="same(row['priority'], 'high') ? cf_open_close.ask(row) : c_open_close.run({ ticket_id: row['id'] as Value })">Close</KitButton>
              </template>
            </template>
          </KitTable>
        </KitPanel>
        <KitEmpty v-if="!groups_open.length" message="No rows." />
      </KitPanel>
      <KitPanel name="closed" title="Closed" collapsible :state="r_closed.state" :error="r_closed.error" @retry="r_closed.reload()">
        <KitSearch label="Find in closed" :model-value="text(page.state['search'])" @update:model-value="page.state['search'] = $event" />
        <KitList label="Closed" :columns="fields_closed" :rows="rows_closed" row-key="id" />
      </KitPanel>
      <KitPanel name="new" title="New ticket" collapsible>
        <KitForm submit-label="Open" :busy="f_new.busy" @submit="f_new.submit()">
          <KitField label="Title" for="new-title">
            <KitTextInput id="new-title" :model-value="text(f_new.draft['title'])" @update:model-value="f_new.draft['title'] = $event" />
          </KitField>
          <KitSelect label="Priority" show-label :options="[{ value: 'high', label: 'high' }, { value: 'normal', label: 'normal' }, { value: 'low', label: 'low' }]" :model-value="f_new.draft['priority']" @update:model-value="f_new.draft['priority'] = $event" />
        </KitForm>
      </KitPanel>
    </KitStack>
  </KitShell>
</template>
